package io.github.diodeme.ji.host;

import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/** Host-owned bootstrap pairing registry for direct Local/SSH Clients. */
public final class HostDeviceRegistry {
    private final String hostId;
    private final LocalTokenService launchTokens;
    private final KeyPair hostIdentity;
    private final Map<String, Device> devices = new ConcurrentHashMap<>();

    public HostDeviceRegistry(String hostId, LocalTokenService launchTokens) {
        if (hostId == null || hostId.isBlank()) throw new IllegalArgumentException("hostId must not be blank");
        this.hostId = hostId;
        this.launchTokens = java.util.Objects.requireNonNull(launchTokens, "launchTokens");
        try {
            hostIdentity = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    public Pairing pair(String operationId, String token, String deviceId, byte[] devicePublicKey) {
        if (operationId == null || operationId.isBlank() || deviceId == null || deviceId.isBlank()
                || devicePublicKey == null || devicePublicKey.length < 32) {
            throw new IllegalArgumentException("invalid device pairing request");
        }
        Device existing = devices.get(deviceId);
        if (existing != null) {
            if (!java.security.MessageDigest.isEqual(existing.publicKey(), devicePublicKey)) {
                throw new IllegalArgumentException("device identity changed");
            }
            return pairing(operationId, existing);
        }
        if (launchTokens.exchange(token, true).isEmpty()) {
            throw new IllegalArgumentException("invalid launch token");
        }
        var device = new Device(deviceId, devicePublicKey, "host-admin");
        Device raced = devices.putIfAbsent(deviceId, device);
        if (raced != null && !java.security.MessageDigest.isEqual(raced.publicKey(), devicePublicKey)) {
            throw new IllegalArgumentException("device identity changed");
        }
        return pairing(operationId, raced == null ? device : raced);
    }

    public Optional<Device> device(String deviceId) {
        return Optional.ofNullable(devices.get(deviceId));
    }

    private Pairing pairing(String operationId, Device device) {
        return new Pairing(operationId, hostId, device.deviceId(), device.role(), hostIdentity.getPublic().getEncoded());
    }

    public record Device(String deviceId, byte[] publicKey, String role) {
        public Device {
            publicKey = publicKey.clone();
        }
        @Override public byte[] publicKey() { return publicKey.clone(); }
        @Override public String toString() { return "Device[deviceId=" + deviceId + ",role=" + role + "]"; }
    }

    public record Pairing(String operationId, String hostId, String deviceId, String role, byte[] hostPublicKey) {
        public Pairing {
            hostPublicKey = hostPublicKey.clone();
        }
        @Override public byte[] hostPublicKey() { return hostPublicKey.clone(); }
        public String hostPublicKeyBase64() { return Base64.getEncoder().encodeToString(hostPublicKey); }
    }
}
